-- Binds the sej-pure.v2 operators the estate's graph runner overlay (sidefx:capability:run-declared-graph/run-declared-graph-execute)
-- does not bind yet, each to the provider that evaluates the operators it already binds (the 'unique' entry's binding).
-- One transaction; nothing commits unless every binding succeeds.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lk int;
EXEC @lk = sys.sp_getapplock @Resource = N'sidefx:model-write', @LockMode = N'Update', @LockOwner = N'Transaction', @LockTimeout = 30000;
IF @lk < 0 THROW 51000, N'MODEL_WRITE_LOCK_UNAVAILABLE', 1;

EXEC model.declare_port_provider_binding @namespace_id = N'sidefx:capability:run-declared-graph', @port_id = N'run-declared-graph-execute', @overlay_binding_json = N'{"mechanicId":"structural-equals","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"}';
EXEC model.declare_port_provider_binding @namespace_id = N'sidefx:capability:run-declared-graph', @port_id = N'run-declared-graph-execute', @overlay_binding_json = N'{"mechanicId":"subtract","providerProfileId":"sda-semantic-value-graph-provider.v1","providerProfileDigest":"sha256:aca6d8863f8ab4557ab31692c6d67cb42a15a98ca2a38fab863db6c14f00d9fd","implementationRef":"sda-semantic-value-graph-provider.v1"}';
